#!/usr/bin/python3
# Python script to reformat iCal feeds generated by TimeEdit to make the event titles more succinct.

# comment this line out if you're not using this as a CGI script'
print("Content-Type: text/calendar;charset=utf-8\n")

# The URL of the calendar field
URL = 'YOUR_URL_HERE'

import icalendar as ical
import requests,random

# You can add custom replace rules here, which will allow you to remove/shorten words in event titles
custom_replaces = [("recorded","rec."),("Computer Science", "CS"), ("Mathematics","Maths"), ("Computer Systems","CompSys"),("Fundmentals of Programming", "FundsOfProg")]

# mode can either be 'write' or 'return'
mode = 'return'
# the file that the reformatted calendar will be saved to if in that mode
filename = 'reformat.ics'

def cust_replace(inString):
    for replaceSet in custom_replaces:
        inString = inString.replace(replaceSet[0],replaceSet[1])
    return inString

with requests.get(URL) as urlhandle:
    calendar = ical.Calendar.from_ical(urlhandle.text)
    for event in calendar.events:
        # Split the title into its fields, pretty jankily
        half = event["SUMMARY"].split(". ")
        module_code = half[0].replace("Module Code: ", "")
        rest = half[1].split(", ")
        module_name = rest[0].replace("Module Name: ", "")
        # If the event has an extra title, other fields move along by one
        if "Title" in rest[1]:
            title = rest[1].replace("Title: ", "")
            activity_type = rest[2].replace("Activity Type: ", "")
            # if a staff list is present
            if len(rest) > 3:
                staff = ',',join(rest[3:])
                staff = staff.replace("Staff: ", "")

        elif "Activity Type" in rest[1]:
            title = '' # this event has no title
            activity_type = rest[1].replace("Activity Type: ", "")
            # if a staff list is present
            if len(rest) > 2:
                staff = ','.join(rest[2:])
                staff = staff.replace("Staff: ", "")
        # Choose what fields to include/not include here:
        formatted = f'{module_code}: {title} {activity_type} w/ {staff}'
        # Run custom replacements on the resulting string
        formatted = cust_replace(formatted)
        # Replace the event title with the new one
        event["SUMMARY"] = formatted
        # You can also optionally add/remove to the description here
        # you could run replacements here as well if you would like
        event["DESCRIPTION"] = f'{module_name} {event["DESCRIPTION"]}'
    # if we are in write mode, write an ics file, or instead send the ics to stdout
    if mode == 'write':
        with open(filename, 'wb') as filehandle:
            filehandle.write(calendar.to_ical())
    elif mode == 'return':
        print(calendar.to_ical().decode('utf-8'))

